<div class="page-head"><div><h1>Gi&#7887; h&#224;ng</h1><div class="muted">T&#7891;n kho v&#224; gi&#225; s&#7869; &#273;&#432;&#7907;c x&#225;c nh&#7853;n l&#7841;i khi &#273;&#7863;t h&#224;ng.</div></div><a class="button secondary" href="store.php?url=Storefront/Get_data">Ti&#7871;p t&#7909;c mua s&#7855;m</a></div><?php if(empty($data['items'])) { ?><div class="empty">Gi&#7887; h&#224;ng &#273;ang tr&#7889;ng.</div><?php } else { ?><div class="panel"><table class="cart-table"><thead><tr><th>S&#7843;n ph&#7849;m</th><th>&#272;&#417;n gi&#225;</th><th>S&#7889; l&#432;&#7907;ng</th><th>Th&#224;nh ti&#7873;n</th><th></th></tr></thead><tbody><?php foreach($data['items'] as $item) { ?><tr><td><div class="cart-product"><?php if($item['HinhAnh']) { ?><img src="Public/Images/<?php echo rawurlencode($item['HinhAnh']); ?>" alt=""><?php } ?><a href="store.php?url=Storefront/ChiTiet/<?php echo rawurlencode($item['MaSP']); ?>"><?php echo htmlspecialchars($item['TenSP'],ENT_QUOTES,'UTF-8'); ?></a></div></td><td><?php echo number_format((float)$item['GiaBan'],0,',','.'); ?> &#8363;</td><td><form class="qty-form" method="post" action="store.php?url=Cart/Update/<?php echo rawurlencode($item['MaSP']); ?>"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['shop_csrf'],ENT_QUOTES,'UTF-8'); ?>"><input type="number" name="quantity" min="0" max="<?php echo (int)$item['SoLuongTon']; ?>" value="<?php echo (int)$item['CartQuantity']; ?>"><button class="button secondary" type="submit">C&#7853;p nh&#7853;t</button></form><small class="muted">T&#7891;n kho: <?php echo (int)$item['SoLuongTon']; ?> &middot; nh&#7853;p 0 &#273;&#7875; b&#7887;</small></td><td><strong><?php echo number_format((float)$item['LineTotal'],0,',','.'); ?> &#8363;</strong></td><td><form method="post" action="store.php?url=Cart/Remove/<?php echo rawurlencode($item['MaSP']); ?>"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['shop_csrf'],ENT_QUOTES,'U